snippet_css:
:root{
  --bg: #F2F0EB;
  --fg: #101010;
  --muted: #4A4A4A;
  --surface: #FFFFFF;
  --border: #101010;
  --accent: #D62828;
  --accent-fg: #FFFFFF;
  --radius: 0px;
  --radius-sm: 0px;
  --shadow: none;
  --btn-shadow: none;
  --art-bg: linear-gradient(135deg,#D62828 0 33%,#F4C300 33% 66%,#0057B8 66%);
  --media-bg: linear-gradient(135deg,#0057B8 0 50%,#F4C300 50%);
  --cta-bg: #101010;
  --input-bg: #FFFFFF;
  --ok: #0057B8;
  --warn: #D62828;
  --font-display: Poppins,'Noto Sans TC',sans-serif;
  --font-body: Inter,'Noto Sans TC',sans-serif;
  --focus-ring: var(--accent);
}

snippet_tailwind:
// tailwind.config.js → theme.extend
{
  "colors": {
    "bg": "#F2F0EB",
    "fg": "#101010",
    "muted": "#4A4A4A",
    "surface": "#FFFFFF",
    "border": "#101010",
    "accent": "#D62828",
    "accent-fg": "#FFFFFF",
    "ok": "#0057B8",
    "warn": "#D62828",
    "focus-ring": "var(--accent)"
  },
  "borderRadius": {
    "DEFAULT": "0px",
    "lg": "0px"
  },
  "fontFamily": {
    "display": [
      "Poppins,'Noto Sans TC',sans-serif"
    ],
    "body": [
      "Inter,'Noto Sans TC',sans-serif"
    ]
  }
}
